+	l, err := m.alloc.reserveNetwork("prepared-" + uuid.NewString())
+	if err != nil {
+		t.Fatal(err)
+	}
+	nc := netns.NewConfig(l.Instance, l.Netns, l.VethHost, l.VethPeer, l.HostIP)
+	if err := m.run.Run(t.Context(), []string{"ip", "netns", "add", nc.Netns}); err != nil {
